const p = $input.first().json.body || {};
if (p.evento !== 'entrada_aprobada') return [];

const correo = String(p.correo || '').trim();
if (!/^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(correo)) {
  throw new Error('La entrada aprobada no tiene un correo válido (id=' + p.id + ')');
}

const qr = String(p.qr_url || '');
const ticket = String(p.ticket_url || '');
if (!/^https:\/\/res\.cloudinary\.com\/[A-Za-z0-9/_.,%~-]+$/.test(qr)) {
  throw new Error('qr_url no apunta a Cloudinary por HTTPS (id=' + p.id + ')');
}
if (!/^https:\/\/integra-code-umber\.vercel\.app\/t\/[A-Za-z0-9_-]{22}$/.test(ticket)) {
  throw new Error('ticket_url no coincide con la web de entradas (id=' + p.id + ')');
}

const esc = (value) => String(value).replace(/[&<>"']/g, (char) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]
);
const nombre = esc(String(p.nombre_completo || 'invitado/a').trim());
const tipo = {
  solo_entrada: 'Entrada',
  entrada_bus: 'Entrada + bus',
  solo_bus: 'Bus'
}[p.tipo_entrada] || 'Entrada';
const qrUrl = esc(qr);
const ticketUrl = esc(ticket);
const html = [
  '<div style="font-family:Arial,sans-serif;color:#1f2937;max-width:560px;margin:auto">',
  '<h1 style="font-size:26px">Tu entrada está aprobada</h1>',
  '<p>Hola, ' + nombre + '.</p>',
  '<p>Tu pase de <strong>' + tipo + '</strong> para Integra CODE ya está listo. Presenta este QR al ingresar.</p>',
  '<p style="text-align:center"><img src="' + qrUrl + '" alt="Código QR de entrada" width="240" height="240" style="display:inline-block;width:240px;height:240px"></p>',
  '<p style="text-align:center"><a href="' + ticketUrl + '" style="display:inline-block;background:#111827;color:#ffffff;padding:12px 20px;text-decoration:none;border-radius:6px">Ver mi entrada</a></p>',
  '<p>Si el QR no aparece en tu correo, abre <a href="' + ticketUrl + '">tu entrada</a> y muéstrala desde allí.</p>',
  '<p style="font-size:13px;color:#6b7280">Este enlace es personal. No lo compartas.</p>',
  '</div>'
].join('');

return [{ json: { correo, asunto: 'Tu entrada para Integra CODE', html } }];
